     8	public class CircularQueue<T> extends AbstractQueue<T> {
     9	    private static final String EMPTY_QUEUE_MESSAGE = "Queue is empty.";
    10	    private static final String FULL_QUEUE_MESSAGE = "Queue is full.";
    11	    private static final String NON_NULL_MESSAGE = "Queue elements must be non-null.";
    12	
    13	    private final Object[] elements;
    14	    private int head;
    15	    private int size;
    16	    private int modificationCount;
    17	
    18	    public CircularQueue(int capacity) {
    19	        if (capacity <= 0) {
    20	            throw new IllegalArgumentException("Capacity must be positive.");
    21	        }
    22	        this.elements = new Object[capacity];
    23	    }
    24	
    25	    public void enqueue(T element) {
    26	        if (!offer(element)) {
    27	            throw new IllegalStateException(FULL_QUEUE_MESSAGE);
    28	        }
    29	    }
    30	
    31	    public T dequeue() {
    32	        requireNotEmpty();
    33	        return removeHeadAndRecordModification();
    34	    }
    35	
    36	    public T peekFront() {
    37	        requireNotEmpty();
    38	        return elementAt(head);
    39	    }
    40	
    41	    public T peekRear() {
    42	        requireNotEmpty();
    43	        return elementAt(indexFromHead(size - 1));
    44	    }
    45	
    46	    public T getFront() {
    47	        return peekFront();
    48	    }
    49	
    50	    public T getRear() {
    51	        return peekRear();
    52	    }
    53	
    54	    public boolean isEmpty() {
    55	        return size == 0;
    56	    }
    57	
    58	    public boolean isFull() {
    59	        return size == elements.length;
    60	    }
    61	
    62	    @Override
    63	    public boolean offer(T element) {
    64	        Objects.requireNonNull(element, NON_NULL_MESSAGE);
    65	        if (isFull()) {
    66	            return false;
    67	        }
    68	        insertAtTail(element);
    69	        recordModification();
    70	        return true;
    71	    }
    72	
    73	    @Override
    74	    public T poll() {
    75	        if (isEmpty()) {
    76	            return null;
    77	        }
    78	        return removeHeadAndRecordModification();
    79	    }
    80	
    81	    @Override
    82	    public T peek() {
    83	        return isEmpty() ? null : elementAt(head);
    84	    }
    85	
    86	    @Override
    87	    public int size() {
    88	        return size;
    89	    }
    90	
    91	    public int capacity() {
    92	        return elements.length;
    93	    }
    94	
    95	    public int remainingCapacity() {
    96	        return capacity() - size;
    97	    }
    98	
    99	    @Override
   100	    public void clear() {
   101	        Arrays.fill(elements, null);
   102	        head = 0;
   103	        size = 0;
   104	        recordModification();
   105	    }
   106	
   107	    @Override
   108	    public Iterator<T> iterator() {
   109	        return new CircularQueueIterator();
   110	    }
   111	
   112	    @Override
   113	    public String toString() {
   114	        StringBuilder builder = new StringBuilder("[");
   115	        for (int i = 0; i < size; i++) {
   116	            if (i > 0) {
   117	                builder.append(',');
   118	            }
   119	            builder.append(elementAt(indexFromHead(i)));
   120	        }
   121	        return builder.append(']').toString();
   122	    }
   123	
   124	    private int advance(int index) {
   125	        return (index + 1) % elements.length;
   126	    }
   127	
   128	    private int tailIndex() {
   129	        return (head + size) % elements.length;
   130	    }
   131	
   132	    private int indexFromHead(int offset) {
   133	        return (head + offset) % elements.length;
   134	    }
   135	
   136	    private void requireNotEmpty() {
   137	        if (isEmpty()) {
   138	            throw new IllegalStateException(EMPTY_QUEUE_MESSAGE);
   139	        }
   140	    }
   141	
   142	    private void insertAtTail(T element) {
   143	        elements[tailIndex()] = element;
   144	        size++;
   145	    }
   146	
   147	    private void recordModification() {
   148	        modificationCount++;
   149	    }
   150	
   151	    private T removeHeadAndRecordModification() {
   152	        T removed = removeHead();
   153	        recordModification();
   154	        return removed;
   155	    }
   156	
   157	    @SuppressWarnings("unchecked")
   158	    private T removeHead() {
   159	        T removed = (T) elements[head];
   160	        elements[head] = null;
   161	        head = advance(head);
   162	        size--;
   163	        return removed;
   164	    }
   165	
   166	    @SuppressWarnings("unchecked")
   167	    private T elementAt(int index) {
   168	        return (T) elements[index];
   169	    }
   170	
   171	    private final class CircularQueueIterator implements Iterator<T> {
   172	        private int offset;
   173	        private final int expectedModificationCount = modificationCount;
   174	
   175	        @Override
   176	        public boolean hasNext() {
   177	            checkForComodification();
   178	            return offset < size;
   179	        }
   180	
   181	        @Override
   182	        public T next() {
   183	            checkForComodification();
   184	            if (offset >= size) {
   185	                throw new NoSuchElementException();
   186	            }
   187	            T value = elementAt(indexFromHead(offset));
   188	            offset++;
   189	            return value;
   190	        }
   191	
   192	        private void checkForComodification() {
   193	            if (expectedModificationCount != modificationCount) {
   194	                throw new ConcurrentModificationException();
   195	            }
   196	        }
   197	    }
   198	}

